SELECT * FROM (SELECT T.* FROM( SELECT ETR_ENTRUST_ADD.ASSET_TYPE1 as assetType1, #{effectFlag} effectFlag, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, decode(ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7) entrustStatusOrder, ETR_ENTRUST.ENTRUST_TYPE entrustType, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.INV_MANAGER_ID invManagerId, su1.real_name invManagerName, nvl(detail.PORTFOLIO_ID,PTL_PORTFOLIO.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,PTL_PORTFOLIO.PORTFOLIO_NAME) portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN ('03', '04','T56','T93','T94','T95','T96') THEN ETR_ENTRUST.STOCK_ID else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') THEN ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND ETR_ENTRUST.PS IN('03','04') AND ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, ETR_ENTRUST.PS Ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, decode( btm.OUTPUT_VALUE_1, 'EX004', '', decode( ETR_ENTRUST_ADD.ASSET_TYPE, 'F01', NVL( ETR_ENTRUST.ENTRUST_NUM * ETR_ENTRUST.PRICE, 0 ), 'F10', NVL( ETR_ENTRUST.ENTRUST_NUM * 100, 0 ), NVL( ETR_ENTRUST.ENTRUST_AMT, ETR_ENTRUST.ENTRUST_NUM ) ) )entrustAmt, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) finishAmt, NVL( ETR_ENTRUST.CCY , 'CNY' ) ccy, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, /*B.TRADER trader, B.realName realName,*/ ETR_ENTRUST.REMARK remark, ETR_ENTRUST_ADD.BUSI_TYPE_POSITION busiTypePosition, ssai.sec_acct_name secAcctId, DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01','','F07',ETR_ENTRUST_ADD.TERM_DAYS,'F10',ETR_ENTRUST_ADD.TERM_DAYS,'F12',ETR_ENTRUST_ADD.TERM_DAYS,'F16',ETR_ENTRUST_ADD.TERM_DAYS,'') termDays, case when ETR_ENTRUST.PS in ('T68', 'T69') or ETR_ENTRUST_ADD.ASSET_TYPE = 'F07' then ETR_ENTRUST.PRICE*100 when decode(ETR_ENTRUST_ADD.PRICE_TYPE,#{PRICE_CLASS_01,jdbcType=VARCHAR},ROUND(ETR_ENTRUST.PRICE,4),#{PRICE_CLASS_02,jdbcType=VARCHAR},ROUND(ETR_ENTRUST_ADD.FULL_PRICE,4)) when ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' then ROUND(ETR_ENTRUST.price,3) else round(decode(btm.OUTPUT_VALUE_1,#{busiTypePosition02},decode(ETR_ENTRUST_ADD.CALCULATE_FIELD,'price',ETR_ENTRUST.PRICE,'exerYield',ETR_ENTRUST_ADD.EXER_YIELD*100,'matureYield',ETR_ENTRUST_ADD.MATURE_YIELD*100),#{busiTypePosition03},ETR_ENTRUST.PRICE,NVL(ETR_ENTRUST.PRICE, 0.00)),4) end as etrPrice, CASE
WHEN ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T5.ORDER_FINISH_AMT, 0 ),0,0, nvl( T5.ORDER_FINISH_AMT, 0 )/ nvl( ETR_ENTRUST.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ) / nvl( ETR_ENTRUST.ENTRUST_AMT, 1 ), 4 )*100 END AS exeProgress, CASE
WHEN ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T5.ENT_FINISH_AMT, 0 ),0,0, nvl( T5.ENT_FINISH_AMT, 0 )/ nvl( ETR_ENTRUST.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( nvl( T5.ENT_FINISH_AMT, 0 ) / nvl( ETR_ENTRUST.ENTRUST_AMT, 1 ), 4 ) *100 END AS dealProgress, CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) END AS execFinishAmt, CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_entrust.ENTRUST_AMT, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) END AS execRemainderAmt, CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) END AS transFinishAmt, CASE
WHEN etr_entrust_add.TARGET_TYPE = '01' THEN ROUND( nvl( etr_entrust.ENTRUST_NUM, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( etr_entrust.ENTRUST_AMT, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) END AS transRemainderAmt, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi:ss') transmitTime, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi') transmitTimeSer, ETR_ENTRUST.PRICE_MODEL priceModel, sci.ACCT_NAME trdAcctId, case when ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX017' then ROUND(ETR_ENTRUST.ENTRUST_NUM/100,2) when ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' then '' else ETR_ENTRUST.ENTRUST_NUM end entrustNum, ETR_ENTRUST_ADD.CALCULATE_FIELD calculateField, mcpdata.COUNTER_NAME counterId, ETR_ENTRUST_ADD.TARGET_TYPE FROM (SELECT * FROM ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN ( SELECT EED.ENTRUST_ID, wm_concat ( FP.PORTFOLIO_ID ) AS PORTFOLIO_ID , wm_concat ( FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL EED left join (select PORTFOLIO_ID,PORTFOLIO_NAME from PTL_PORTFOLIO order by PORTFOLIO_ID, PORTFOLIO_NAME) FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON ETR_ENTRUST.ENTRUST_ID = detail.ENTRUST_ID
/* LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID*/ LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
/*LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID*/ LEFT JOIN ETR_FINISH_STATUS T5 ON T5.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID AND ETR_ENTRUST.ENTRUST_ID = T5.TRADE_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON ETR_ENTRUST_ADD.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO sci ON sci.ACCT_NO = ssai.TRD_ACCT_ID LEFT JOIN SYS_USER su1 ON ETR_ENTRUST.INV_MANAGER_ID = su1.USER_NAME /*LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON (ETR_ENTRUST.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 is null) AND (ETR_ENTRUST.Ps = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 is null) AND (ETR_ENTRUST.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL)*/ left join MST_COUNTER_PARTY mcpdata on ETR_ENTRUST.COUNTER_ID = mcpdata.COUNTER_ID
AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustAwait},#{entrustDistribute},#{entrustReceive},#{entrustUntread},#{entrustClose},#{entrustReturn},#{entrustRecall},#{entrustInwfl})
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND ETR_ENTRUST.PORTFOLIO_ID IN(
#{item}
)
AND ETR_ENTRUST.PS = #{ps}
AND ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2}
AND ETR_ENTRUST_ADD.BUSI_TYPE_POSITION = #{busiTypePosition}
AND FIN_PRODUCT.FINPROD_MARKET_ID IN(
#{item}
)
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND ETR_ENTRUST_ADD.SEC_ACCT_ID IN(
#{item}
)
AND ETR_ENTRUST.ENTRUST_ID LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
AND ETR_ENTRUST.INV_MANAGER_ID IN(
#{item}
)
AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') >= #{entrustStartDate} AND to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') <= #{entrustEndDate}
AND ETR_ENTRUST.CCY = #{ccy}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND sci.ACCT_NO = #{trdAcctId}
AND ssai.SEC_ACCT_NAME = #{trdAcctName} LIKE concat(concat('%',#{entrustId,jdbcType=VARCHAR}),'%')
union all SELECT WFL_ETR_ENTRUST_ADD.ASSET_TYPE1 as assetType1, #{effectFlag04} effectFlag, WFL_ETR_ENTRUST.ENTRUST_STATUS entrustStatus, decode(WFL_ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7) entrustStatusOrder, WFL_ETR_ENTRUST.ENTRUST_TYPE entrustType, WFL_ETR_ENTRUST.ENTRUST_ID entrustId, WFL_ETR_ENTRUST.INV_MANAGER_ID invManagerId, su1.real_name invManagerName, nvl(detail.PORTFOLIO_ID,PTL_PORTFOLIO.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,PTL_PORTFOLIO.PORTFOLIO_NAME) portfolioName, WFL_ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN ('03', '04','T56','T93','T94','T95','T96') THEN WFL_ETR_ENTRUST.STOCK_ID else(case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else WFL_ETR_ENTRUST_ADD.ASSET_TYPE_10 end) end finprodMarketId, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN('03','04') THEN WFL_ETR_ENTRUST.STOCK_ID ELSE FIN_PRODUCT.FINPROD_ID END finprodId, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE ='F07' AND WFL_ETR_ENTRUST.PS IN('03','04') AND WFL_ETR_ENTRUST.ENTRUST_TYPE NOT IN ('17', '18', '19', '20', '21') THEN WFL_ETR_ENTRUST.FINPROD_ID else (case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end) end finprodAbbr, WFL_ETR_ENTRUST.PS Ps, CASE WHEN WFL_ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = WFL_ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = WFL_ETR_ENTRUST.PS) END AS otherPs, WFL_ETR_ENTRUST_ADD.BUSI_PS busiPs, WFL_ETR_ENTRUST.TRADE_MARKET tradeMarket, decode( ETR_ENTRUST_ADD.BUSI_TYPE_POSITION, 'EX004', '', decode( WFL_ETR_ENTRUST_ADD.ASSET_TYPE, 'F01', NVL( WFL_ETR_ENTRUST.ENTRUST_NUM * WFL_ETR_ENTRUST.PRICE, 0 ), 'F10', NVL( WFL_ETR_ENTRUST.ENTRUST_NUM * 100, 0 ), NVL( WFL_ETR_ENTRUST.ENTRUST_AMT, WFL_ETR_ENTRUST.ENTRUST_NUM ) ) )entrustAmt, /*decode(WFL_ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUSA.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUSA.FINISH_AMT,0)) */ 0 finishAmt, NVL( WFL_ETR_ENTRUST.CCY , 'CNY' ) ccy, WFL_ETR_ENTRUST.ENTRUST_DATE entrustDate, WFL_ETR_ENTRUST.VDATE vdate, WFL_ETR_ENTRUST.MDATE mdate, /* B.TRADER trader, B.realName realName,*/ WFL_ETR_ENTRUST.REMARK remark, ETR_ENTRUST_ADD.BUSI_TYPE_POSITION busiTypePosition, ssai.sec_acct_name secAcctId, DECODE(WFL_ETR_ENTRUST_ADD.SETTLE_SPREED,0,'01',1,'02','2','03') settleSpeed, decode(WFL_ETR_ENTRUST_ADD.ASSET_TYPE,'F01','','F07',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F10',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F12',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'F16',WFL_ETR_ENTRUST_ADD.TERM_DAYS,'') termDays, case when WFL_ETR_ENTRUST.PS in ('T68', 'T69') or WFL_ETR_ENTRUST_ADD.ASSET_TYPE = 'F07' then WFL_ETR_ENTRUST.PRICE*100 when decode(WFL_ETR_ENTRUST_ADD.PRICE_TYPE,#{PRICE_CLASS_01,jdbcType=VARCHAR},ROUND(WFL_ETR_ENTRUST.PRICE,4),#{PRICE_CLASS_02,jdbcType=VARCHAR},ROUND(ETR_ENTRUST_ADD.FULL_PRICE,4)) when WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' then ROUND(WFL_ETR_ENTRUST.price,3) else round(decode(btm.OUTPUT_VALUE_1,#{busiTypePosition02},decode(WFL_ETR_ENTRUST_ADD.CALCULATE_FIELD,'price',WFL_ETR_ENTRUST.PRICE,'exerYield',WFL_ETR_ENTRUST_ADD.EXER_YIELD*100,'matureYield',WFL_ETR_ENTRUST_ADD.MATURE_YIELD*100),#{busiTypePosition03},WFL_ETR_ENTRUST.PRICE,NVL(WFL_ETR_ENTRUST.PRICE, 0.00)),4) end as etrPrice, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T5.ORDER_FINISH_AMT, 0 ), 0, 0, nvl( T5.ORDER_FINISH_AMT, 0 )/ nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ) / nvl( WFL_ETR_ENTRUST.ENTRUST_AMT, 1 ), 4 )*100 END AS*/ 0 exeProgress, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T5.ENT_FINISH_AMT, 0 ), 0, 0, nvl( T5.ENT_FINISH_AMT, 0 )/ nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 1 )), 4 )*100 ELSE ROUND( nvl( T5.ENT_FINISH_AMT, 0 ) / nvl( WFL_ETR_ENTRUST.ENTRUST_AMT, 1 ), 4 )*100 END AS*/ 0 dealProgress, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) END AS*/ 0 execFinishAmt, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 0 ) - nvl( T5.ORDER_FINISH_AMT, 0 ), 4 ) END AS*/ 0 execRemainderAmt, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) END AS*/ 0 transFinishAmt, /*CASE
WHEN WFL_ETR_ENTRUST_ADD.TARGET_TYPE = '01' THEN ROUND( nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( WFL_ETR_ENTRUST.ENTRUST_NUM, 0 ) - nvl( T5.ENT_FINISH_AMT, 0 ), 4 ) END AS*/ 0 transRemainderAmt, NULL transmitTime, NULL transmitTimeSer, WFL_ETR_ENTRUST.PRICE_MODEL priceModel, sci.ACCT_NAME trdAcctId, case when WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX017' then ROUND(WFL_ETR_ENTRUST.ENTRUST_NUM/100,2) when WFL_ETR_ENTRUST_ADD.BUSI_TYPE_POSITION='EX018' then '' else WFL_ETR_ENTRUST.ENTRUST_NUM end entrustNum, WFL_ETR_ENTRUST_ADD.CALCULATE_FIELD calculateField, mcpdata.COUNTER_NAME counterId, WFL_ETR_ENTRUST_ADD.TARGET_TYPE FROM (SELECT * FROM WFL_ETR_ENTRUST ORDER BY ENTRUST_DATE DESC) WFL_ETR_ENTRUST LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = WFL_ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = WFL_ETR_ENTRUST.FINPROD_ID LEFT JOIN ( SELECT EED.ENTRUST_ID, wm_concat ( FP.PORTFOLIO_ID ) AS PORTFOLIO_ID , wm_concat ( FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL EED left join (select PORTFOLIO_ID,PORTFOLIO_NAME from PTL_PORTFOLIO order by PORTFOLIO_ID, PORTFOLIO_NAME) FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON WFL_ETR_ENTRUST.ENTRUST_ID = detail.ENTRUST_ID /*LEFT JOIN (SELECT listagg(TRADER, ',') within group ( order by TRADER ) TRADER, listagg(REAL_NAME, ',') within group(order by TRADER) realName, ENTRUST_ID as ENTRUST_ID FROM ETR_DISTRIBUTE LEFT JOIN SYS_USER ON ETR_DISTRIBUTE.TRADER = SYS_USER.USER_NAME GROUP BY ENTRUST_ID)B ON B.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) ETR_FINISH_STATUSA ON ETR_FINISH_STATUSA.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID*/ LEFT JOIN WFL_ETR_ENTRUST_ADD ON WFL_ETR_ENTRUST.ENTRUST_ID = WFL_ETR_ENTRUST_ADD.ENTRUST_ID /*LEFT JOIN OPT_TARGET_INFO ON WFL_ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID LEFT JOIN FIN_PRODUCT_TYPE_CONFIG btm ON (WFL_ETR_ENTRUST.FINPROD_TYPE2 = btm.INPUT_VALUE_2 OR btm.INPUT_VALUE_2 is null) AND (WFL_ETR_ENTRUST.Ps = btm.INPUT_VALUE_3 OR btm.INPUT_VALUE_3 is null) AND (WFL_ETR_ENTRUST.TRADE_PLAT = btm.INPUT_VALUE_1 OR btm.INPUT_VALUE_1 IS NULL)*/
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
/* LEFT JOIN (SELECT listagg(BID_PRICE, ',') within group (order by BID_PRICE) BID_PRICE, ENTRUST_ID as ENTRUST_ID FROM ETR_ENTRUST_BID_PRICE GROUP BY ENTRUST_ID) EEBP ON EEBP.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_FINISH_STATUS T5 ON T5.ENTRUST_ID = WFL_ETR_ENTRUST.ENTRUST_ID AND WFL_ETR_ENTRUST.ENTRUST_ID = T5.TRADE_ID*/ LEFT JOIN STL_SEC_ACCT_INFO ssai ON WFL_ETR_ENTRUST_ADD.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO sci ON sci.ACCT_NO = ssai.TRD_ACCT_ID LEFT JOIN SYS_USER su1 ON WFL_ETR_ENTRUST.INV_MANAGER_ID = su1.USER_NAME left join MST_COUNTER_PARTY mcpdata on WFL_ETR_ENTRUST.COUNTER_ID = mcpdata.COUNTER_ID
